from pathlib import Path
import json,hashlib,datetime
OUT=Path(__file__).resolve().parent;C=Path('/tmp/medina-c64-source-cache');NOW=datetime.datetime.now(datetime.timezone.utc).isoformat();rows=[]
meta={x['id']:x for f in ['retrieval.json','fi-retrieval.json','fi2-retrieval.json'] for x in json.loads((C/f).read_text())}
def add(i,base,section,passage,pop='Adultes avec masse ou carcinome rénal',limits='Lecture ciblée ; décision individualisée.',url=None,publisher=None,path=None):
 m=meta.get(base,{});p=Path(path) if path else C/(base+'.raw');p=p if p.exists() else C/(base+'.txt')
 rows.append(dict(id=i,url=url or m['url'],publisher=publisher or ('EAU, Renal Cell Carcinoma, limited update March2026' if base=='EU-EAU2026' else 'Information professionnelle suisse Swissmedic/AIPS via AmiKo' if base.startswith('FI-') else base),section=section,passage=passage,passage_type='faithful_paraphrase',population=pop,limits=limits,limitations=limits,read_at=NOW,reader='astra_nephrologie',cache_path=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),reading_scope='selected_sections_actually_read'))
add('CH-EPI','CH-EPI','Chiffres clés C64, moyennes annuelles2018–2022','Le monitoring national rapporte819nouveaux cas chez les hommes et352chez les femmes par an en moyenne ;193et105décès. Les icônes de sexe et les légendes ont été vérifiées dans le HTML.','Population suisse, catégorieC64,2018–2022','Moyennes annuelles arrondies ; ne pas attribuer tous les cas à la seule histologie à cellules claires.',publisher='OFS, Monitorage du cancer, données2025')
add('CH-MASSES','CH-RMS-MASSES','RMS2018;14:2160–2163, quatre pages cliniques','La prise en charge des petites masses solides confronte probabilité tumorale, utilité de la biopsie, fonction rénale et risques opératoires. La préservation néphronique et la discussion multidisciplinaire sont centrales.',limits='Revue2018 : chiffres anciens, papillaireI/II et affirmation absolue sur absence d’essaimage corrigés par EAU2026 ; figures non réutilisées.',publisher='Liernur, Iselin, Klein ; HUG/Revue Médicale Suisse2018')
add('CH-INSEL','CH-INSEL','Tumeurs du parenchyme rénal : diagnostic et chirurgieT1','Les masses rénales sont souvent découvertes fortuitement. Tabac, obésité, hypertension et histoire familiale orientent le risque. La chirurgie partielle est privilégiée pour les tumeursT1 lorsque faisable.',limits='Page non datée : proportions histologiques, traitement systémique, radiothérapie et suivi uniformisé non retenus ; actualisation par EAU2026.',publisher='Inselspital, Clinique universitaire d’urologie Berne')
sections=[
('EU-EPI','§3,pp.8–10','Tabac, obésité et hypertension sont des facteurs de risque ; pas de dépistage systématique validé en population générale. Les observations sur alcool ne justifient pas de conseil de consommation.','Les données européennes et suisses ont des populations différentes ; pas de mélange de dénominateurs.'),
('EU-HISTO','§3.4,pp.10–16','OMS2022 distingue notamment cellules claires, papillaire et chromophobe ; division papillaireI/II abandonnée. Sarcomatoïde désigne une dédifférenciation. L’oncocytome ne peut être affirmé définitivement sur biopsie à l’aiguille selon OMS2022.','Pas d’identification histologique certaine par image radiologique ; WHO/ISUP ne s’applique pas au chromophobe. p.16 non utilisée.'),
('EU-TNM','§4,pp.17–18,tableau4.1','La classification TNM2017 sépare tumeur confinée au rein, extension veineuse ou graisseuse et franchissement du fascia de Gerota. T1≤7cm, T1a≤4cm ; le stade intègre N et M.','Edition2017 explicitement reproduite dans EAU2026 ; stade anatomique distinct du grade et du score pronostique.'),
('EU-DX','§5.1–5.2,pp.18–22','Anamnèse, examen et biologie évaluent manifestations locales, systémiques et fonction. CT multiphasique caractérise rehaussement et extension ; IRM aide notamment pour thrombus veineux. Le rehaussement ne donne pas à lui seul l’histologie.','Triade rare ; une absence de symptômes ou une créatinine normale n’exclut pas une tumeur. Seuil≥15HU dépend de phases comparables.'),
('EU-BIOPSY','§5.3 et recommandations,pp.22–24','Biopsie carottée coaxiale si le résultat peut changer la conduite, avant ablation ou traitement systémique sans histologie. Un prélèvement non diagnostique appelle réévaluation ; l’essaimage est rare mais possible.','Performance99,1%/99,7% concerne les biopsies diagnostiques ; environ8%non diagnostiques. Ne pas biopsier un kyste sans composante solide significative.'),
('EU-GENETIC','§5.5,p.24 et§8,pp.75–77','Orientation génétique notamment≤46ans, bilatéralité/multifocalité, histoire familiale ou histologie évocatrice. Les tests constitutionnels sont distincts du profil tumoral. VHL et FH n’autorisent pas les mêmes délais opératoires.','Seuil de3cm de certains syndromes VHL ne s’applique pas aux tumeurs agressives FH ; pas dépistage général de population.'),
('EU-RISK','§6,pp.25–31','Le pronostic intègre TNM, grade et histotype. Leibovich2003 concerne la récidive après chirurgie du carcinome à cellules claires ; IMDC compte six facteurs en maladie métastatique. L’âge seul ne décide pas de l’opérabilité.','IMDC, Leibovich et critères KEYNOTE-564 ont des finalités et populations distinctes ; PD-L1 n’est pas un test de sélection standard RCC.'),
('EU-LOCAL','§7.2,pp.32–34,39–40,44','Néphrectomie partielle pourT1 si faisable ; stratégie personnaliséeT2 et rein unique/CKD. Surveillance active signifie imagerie avec possibilité d’intervention différée, distincte d’attente symptomatique. Ablation ou SABR peuvent être discutées chez certains patients non opérables.','Bénéfice de survie globale PN contre RN non établi avec certitude ; alternatives pas toutes équivalentes à chirurgie. Marge microscopique positive ne signifie pas néphrectomie complémentaire automatique.'),
('EU-ADJ','§7.3.5,pp.48–50,tableau7.1p.52,recommandationsp.53','Pembrolizumab adjuvant chez certains carcinomes à cellules claires à haut risque selon KEYNOTE-564 ; restadification et décision partagée, préférentiellement12–16semaines après chirurgie. Les résultats montrent un bénéfice de survie, avec risque de toxicité et surtraitement.','Les essais négatifs d’autres immunothérapies empêchent de conclure à un effet de classe ; HR0,62 n’est pas une réduction absolue de38points. Ancienne phrase contradictoire sur absence de donnéesOSp.50 écartée au profit des résultats et recommandations actualisées.'),
('EU-MET','§7.4,p.55 ;§7.5,pp.60,65–71','Première ligne métastatique à cellules claires fondée sur immunothérapies combinées selon risque, contexte et possibilités. Pas de néphrectomie cytoréductrice immédiate systématique chez les patients ayant besoin d’un traitement systémique ; éviter chez mauvais risque.','Recommandations européennes ne modifient pas les indications suisses. Les preuves sont moins solides dans les histologies non claires ; les exceptions médullaires ne se traitent pas comme un ccRCC courant.'),
('EU-MOLEC','§7.5.2,pp.57–60','InactivationVHL, accumulationHIF puis augmentationVEGF/PDGF favorisent angiogenèse. Les anti-PD1 et anti-CTLA4 restaurent des fonctions immunes ; les inhibiteursVEGFR visent une autre voie. Belzutifan inhibeHIF2alpha.','Mécanismes ne prédisent pas à eux seuls la réponse individuelle. Belzutifan cité comme mécanisme/option ultérieure européenne, sans dose ni revendication d’autorisation suisse.'),
('EU-FOLLOW','§9,pp.78–81,tableau9.1','Suivi individualisé oncologique et fonctionnel après traitement curatif, stratifié par risque. Le calendrier deCTthorax/abdomen diffère selon Leibovich ; fonction rénale et santé cardiovasculaire restent surveillées au-delà de l’imagerie.','Calendrier expert après chirurgie, non universel après ablation. Pas de preuve qu’une imagerie toujours plus intensive améliore la survie globale.')]
for i,s,p,l in sections:add(i,'EU-EAU2026',s,p,limits=l)
fi={
'KEYTRUDA':('RCC ; posologie IV ; insuffisances ; toxicités immunes','IV200mg/3semaines ou400mg/6semaines en30minutes ; adjuvant≤12mois. Première ligne avec axitinib5mg2fois/j ou lenvatinib20mg/j au risque intermédiaire/défavorable ; augmentation axitinib après≥6semaines en association.','GTIN7680662310025 IV, pas sous-cutané. Cache texte C85 inchangé ; hash du texte et non du HTML. Pas d’extrapolation d’indications d’un autre cancer.'),
'OPDIVO':('RCC ; doses ; organes ; contre-indications','RCC intermédiaire/défavorable : nivolumab3mg/kg+ipilimumab1mg/kg toutes3semaines4doses puis nivolumab240mg/2semaines ; association cabozantinib40mg/j avec nivolumab240mg/2semaines.','GTIN7680656600019 IV. Entretien480mg/4semaines non transposé d’une autre indication. Insuffisance rénale sévère : données limitées.'),
'YERVOY':('RCC ; posologie combinée et durée','Association nivolumab au risque intermédiaire/défavorable ; ipilimumab1mg/kg IV30minutes avec nivolumab3mg/kg, toutes3semaines pour4doses. Nivolumab est administré avant ipilimumab.','GTIN7680617980013 ; ne pas inverser les doses du mélanome et du rein. Toxicités immunes, suivi spécialisé.'),
'CABOMETYX':('Indications ; posologie ; fonctions ; précautions','Monothérapie60mg/j après traitementVEGF ; première ligne avec nivolumab40mg/j au risque intermédiaire/défavorable. Réductions différentes en mono/association ; prise à jeun2havant et1haprès. Prudence rénale, sévère non recommandé ; ChildB sans recommandation de dose, ChildC non recommandé.','GTIN7680664710014 couvre les dosages20/40/60mg ; indication suisse monothérapie plus restreinte que certaines recommandationsEAU. Risques HTA, protéinurie, hémorragie et cicatrisation.'),
'INLYTA':('Indication propre ; posologie ; adaptations ; sécurité','Dose initiale5mg2fois/j ; baisse3puis2mg2fois/j si nécessaire. FIpropre après échec systémique ; indication première ligne combinée dans FIKeytruda. ChildB : réduction initiale par exemple2mg2fois/j ; pas d’ajustement rénal selonFI.','GTIN7680622810015 ; escalade après2semaines monothérapie ne remplace pas délai≥6semaines en combinaison. HTA, thyroïde, hémorragie, protéinurie et interactionsCYP3A4.'),
'KISPLYX':('RCC ; posologie ; adaptations ; sécurité','Première ligne intermédiaire/défavorable avec pembrolizumab : lenvatinib20mg/j ; réductions14,10,8mg. Insuffisance rénale sévère ou ChildC : initial10mg/j ; terminale non recommandé.','GTIN7680660850011 renal, pas Lenvima. Fonction rénale, pression et protéinurie à surveiller ; pas de dose pédiatriqueRCC.'),
'SUTENT':('RCC ; posologie ; organes ; risques cardiaques/hépatiques','RCC avancé/métastatique :50mg/j pendant4semaines puis2semainespause ; ajustements12,5mg. Pas d’ajustement initial rénal même dialyse, mais efficacité clinique non étudiée dans ce groupe.','GTIN7680575630067 ; ne pas copier37,5mgcontinu du cancer neuroendocrine pancréatique. HTA, cœur/QT, thyroïde, numération, foie, protéines etCYP3A4.'),
'VOTRIENT':('RCC ; posologie ; fonctions ; surveillance','RCC avancé/métastatique :800mg/j à jeun1havant ou2haprès repas ; réduction initiale400mg puis paliers200mg. Pas d’ajustement si clairance≥30mL/min ; sévère/dialyse non recommandé. Hépatique modérée200mg/j, sévère contre-indiquée.','GTIN7680603260020. Foie aux semaines3,5,7,9 puis mois3/4 et régulièrement ; HTA, QT, protéinurie et interactions. Ne pas associer automatiquement à pembrolizumab.')}
for k,(s,p,l) in fi.items():add('FI-'+k,'FI-'+k,s,p,pop='Adultes, produit suisse exact et indication RCC',limits=l)
add('NORMAL-KIDNEY','', '§25.3, anatomie externe, interne, hile, néphrons','Reins rétropéritonéaux, cortex et médulla ; urine des papilles vers calices, pelvis et uretère. Vaisseaux rénaux relient aorte et veine cave. Le néphron forme puis modifie le filtrat.','Anatomie humaine normale','Texte paraphrasé, pas de figure de l’édition actuelle réutilisée ; les figures historiques ont leurs licences propres.',url='https://openstax.org/books/anatomy-and-physiology-2e/pages/25-3-gross-anatomy-of-the-kidney',publisher='OpenStax Anatomy and Physiology2e',path='/tmp/medina-n29-source-cache/OPENSTAX25_3.raw')
