add('CH-MEBEKO','','Introduction et§2.1,examen2026','Examen fédéral composé de connaissances et compétences cliniques, construit à partir d’un blueprint multidimensionnel.','Examen2026','Texte extrait fourni en cache, hash du texte ; ne pas confondre PROFILES2017 et édition2023.',url='https://www.bag.admin.ch/dam/fr/sd-web/fL9EvX0YPT2d/20260204_Exigences%20MED%202026_f.pdf',publisher='MEBEKO,3mars2026',path='/workspace/medina-source-cache/C85/mebeko2026.md')
